from taf.ul.trs_e2e_fw.lib.utils.front_haul_modules.bb_module.bb_module import BaseBandModule


def bbmodule_setup(**kwargs):
    """
    Login to baseband module

    *Usage*:
        Bbmodule Setup <config_device>  <alias>  <timeout>  <fsp_id>


    | *Arguments* | *Default Value* | *Comments* | *Config Ref* |
    | config_device | 'bts' | Name of the section in testline config  | `testline_config` |
    |  |  | file which contains the feilds  ip, port, make, password, enable_password, |  |
    |  |  | and configure_prompt. |  |
    | alias | 'default' | Name of execution context |  |
    | timeout | 10 | Timeout for connection in seconds |  |
    | fsp_id | fsp-1a | fsp id to fetch IPv6 address from eNB |  |

    *Example*
    | *keyword* | *device* | *command_profile* |
    | *Bbmodule Setup* | config_device='bts' | alias='bb_session1' | fsp_id='fsp-2a' |

    *Returns* \n
    This keyword returns nothing. By default None will be returned.

    *Possible Exceptions* \n
    IPAddressNotFound : if the IPv6 address is not found is not found in the eNB for
                        corresponding fsp_id.
    """
    BaseBandModule().bbmodule_setup(**kwargs)


def bbmodule_teardown(**kwargs):
    """
       Teardown the baseband module connection

    *Usage*:
        Bbmodule Teardown <alias>


    | *Arguments* | *Default Value* | *Comments* | *Config Ref* |
    | alias | 'default' | Name of execution context |  |

    *Example*
    | *keyword* | *device* | *command_profile* |
    | *Bbmodule Teardown* | alias='bb_session1' |

    *Returns* \n
    This keyword returns nothing. By default None will be returned.

    *Possible Exceptions* \n
    SSHException : If established SSH connection is not available to close.
    """
    BaseBandModule().bbmodule_teardown(**kwargs)
